import React from "react";
import { motion } from "framer-motion";

const BoxesCore = (props) => {
  const { className = "" } = props;
  const rows = new Array(150).fill(1);
  const cols = new Array(100).fill(1);
  const colors = [
    "#93c5fd", "#f9a8d4", "#86efac", "#fde047",
    "#fca5a5", "#d8b4fe", "#a5b4fc", "#c4b5fd",
  ];
  
  const getRandomColor = () => colors[Math.floor(Math.random() * colors.length)];

  return (
    <div
      style={{
        transform: "translate(-40%,-60%) skewX(-48deg) skewY(14deg) scale(0.675) rotate(0deg) translateZ(0)",
      }}
      className={`absolute left-1/4 top-0 z-10 flex h-full w-full p-4 ${className}`}
    >
      {rows.map((_, i) => (
        <motion.div
          key={"row" + i}
          className="relative h-8 w-16 border-l border-slate-700"
        >
          {cols.map((_, j) => (
            <motion.div
              whileHover={{
                backgroundColor: getRandomColor(),
                transition: { duration: 0 },
              }}
              animate={{
                backgroundColor: "transparent",
                transition: { duration: 2 },
              }}
              key={"col" + j}
              className="relative h-8 w-16 border-t border-r border-slate-700 cursor-pointer"
              style={{ backgroundColor: "transparent" }}
            >
              {j % 2 === 0 && i % 2 === 0 ? (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                  strokeWidth="1.5"
                  stroke="currentColor"
                  className="pointer-events-none absolute -top-[14px] -left-[22px] h-6 w-10 stroke-[1px] text-slate-700"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v12m6-6H6" />
                </svg>
              ) : null}
            </motion.div>
          ))}
        </motion.div>
      ))}
    </div>
  );
};

export const Boxes = React.memo(BoxesCore);
